// Verify the HMAC signature Convex put on this request, over the exact raw
// bytes received, and reject stale timestamps (replay window: 5 minutes).
const crypto = require('crypto');
const headers = $input.first().json.headers || {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = String(headers['x-lendloop-signature'] || '');
const secret = $env.LENDLOOP_TO_N8N_SECRET;
const reject = (reason) => [{ json: { valid: false, reason } }];

let raw = '';
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (error) {
  return reject('missing body');
}
if (!secret) return reject('not configured');
if (!timestamp || !signature) return reject('missing signature');
if (Math.abs(Date.now() - Number(timestamp)) > 5 * 60 * 1000) return reject('stale');

const expected = Buffer.from(
  'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex'),
);
const received = Buffer.from(signature);
if (expected.length !== received.length || !crypto.timingSafeEqual(expected, received)) {
  return reject('bad signature');
}

const payload = JSON.parse(raw);
// Convex retries on timeouts, so the same delivery can arrive twice. Delivery
// IDs we've already handled are kept in workflow static data (production runs).
const state = $getWorkflowStaticData('global');
const duplicate = (state.deliveries || []).includes(payload.deliveryId);
return [{ json: { valid: true, duplicate, payload } }];

// Build the message from the minimal payload. Only the recipient's address is
// present; the other party is identified by first name only.
const p = $input.first().json.payload;
const app = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
const dates = `${p.loan.startDate} to ${p.loan.endDate}`;
const who = p.otherParty.firstName;
const tool = p.tool.name;
const messages = {
  'loan.requested': [`${who} wants to borrow your ${tool}`,
    `${who} has asked to borrow your ${tool} (${dates}).\n\nApprove or decline: ${app}/incoming`],
  'loan.cancelled': [`${who} cancelled their request for your ${tool}`,
    `${who} no longer needs your ${tool} for ${dates}. Nothing else to do.`],
  'loan.approved': [`${who} said yes: ${tool}`,
    `${who} approved your request to borrow their ${tool} (${dates}).\n\nDetails: ${app}/requests`],
  'loan.declined': [`Your request for ${tool} was declined`,
    `Your request to borrow ${tool} for ${dates} was declined. Other tools: ${app}/tools`],
  'loan.returned': [`Thanks for returning ${tool}`,
    `${who} marked their ${tool} as returned. Thanks for looking after it.`],
};
const message = messages[p.event];
if (!message) throw new Error(`Unknown event type: ${p.event}`);
return [{ json: {
  to: p.recipient.email,
  subject: message[0],
  text: `Hi ${p.recipient.firstName},\n\n${message[1]}\n\nLendLoop`,
  deliveryId: p.deliveryId,
  loanId: p.loan.id,
} }];

const crypto = require('crypto');
function signed(bodyObject) {
  const body = JSON.stringify(bodyObject);
  const timestamp = String(Date.now());
  const signature = 'sha256=' + crypto
    .createHmac('sha256', $env.N8N_TO_LENDLOOP_SECRET)
    .update(`${timestamp}.${body}`)
    .digest('hex');
  return { body, timestamp, signature };
}

// Remember this delivery so a Convex retry does not email twice, and prepare
// the signed write-back for the loan's activity log.
const { deliveryId, loanId } = $('Compose message').first().json;
const state = $getWorkflowStaticData('global');
state.deliveries = [...(state.deliveries || []), deliveryId].slice(-1000);
return [{ json: signed({
  idempotencyKey: `notify:${deliveryId}`,
  loanId,
  kind: 'request_notification',
  status: 'sent',
}) }];
